//! 📥️ Precise typed PNG fields reconstructed without PNG parsing.
use super::*;
fn boolean(row:&SqliteRow,column:usize)->Result<bool> {Ok(uint(row,column,1)?==1)}
fn optional_integer(database:&SqliteDatabase,table:&str,control:&mut SqliteSnapshotControl<'_>)->Result<Option<u32>> {control.checkpoint(RECONSTRUCT,0,1)?;optional(database,table)?.map(|row|uint(row,1,u32::MAX)).transpose()}
pub(crate) fn reconstruct(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<PngSnapshot> {
 validate_sqlite_database_schema_controlled(database,SQL,RECONSTRUCT,control)?;control.check_database(database,RECONSTRUCT)?;
 let row=database.table("png_image")?.single_row()?;if row.rowid!=1||row.integer(0)?!=1 {return Err(invalid("PNG image identity must be one"));}
 let schema=reconstruct_text(control,row.text(1)?)?;
 let sample_rows=ordered(database.table("png_sample")?,control)?;let mut samples=allocate(sample_rows.len(),control)?;for (index,row) in sample_rows.iter().enumerate() {samples.push(uint(row,3,65535)? as u16);if index%256==0 {control.checkpoint(RECONSTRUCT,index,sample_rows.len())?;}}
 let palette_rows=ordered(database.table("png_palette_entry")?,control)?;let palette=if boolean(row,7)? {let mut palette=allocate(palette_rows.len(),control)?;for row in palette_rows {palette.push(PngRgb {r:uint(row,3,255)? as u8,g:uint(row,4,255)? as u8,b:uint(row,5,255)? as u8});}Some(palette)}else {if !palette_rows.is_empty() {return Err(invalid("PNG absent palette contains entries"));}None};
 let alpha_rows=ordered(database.table("png_alpha")?,control)?;let mut alpha=allocate(alpha_rows.len(),control)?;for row in alpha_rows {alpha.push(uint(row,3,255)? as u8);}
 let transparency=optional(database,"png_transparency")?.map(|row|->Result<PngTransparency> {let first=uint(row,2,65535)? as u16;let second=uint(row,3,65535)? as u16;let third=uint(row,4,65535)? as u16;match uint(row,1,3)? {0 if second==0&&third==0&&alpha.is_empty()=>Ok(PngTransparency::Grayscale {gray:first}),2 if alpha.is_empty()=>Ok(PngTransparency::Rgb {r:first,g:second,b:third}),3 if first==0&&second==0&&third==0=>Ok(PngTransparency::Indexed {alpha:std::mem::take(&mut alpha)}),_=>Err(invalid("PNG transparency has an undeclared typed field"))}}).transpose()?;if !alpha.is_empty() {return Err(invalid("PNG alpha samples have no indexed transparency owner"));}
 let background=optional(database,"png_background")?.map(|row|->Result<PngBackground> {let first=uint(row,2,65535)? as u16;let second=uint(row,3,65535)? as u16;let third=uint(row,4,65535)? as u16;match uint(row,1,3)? {0 if second==0&&third==0=>Ok(PngBackground::Grayscale {gray:first}),2=>Ok(PngBackground::Rgb {r:first,g:second,b:third}),3 if first<=255&&second==0&&third==0=>Ok(PngBackground::Indexed {index:first as u8}),_=>Err(invalid("PNG background has an undeclared typed field"))}}).transpose()?;
 let chromaticities=optional(database,"png_chromaticities")?.map(|row|->Result<PngChromaticities> {Ok(PngChromaticities {white_x:uint(row,1,u32::MAX)?,white_y:uint(row,2,u32::MAX)?,red_x:uint(row,3,u32::MAX)?,red_y:uint(row,4,u32::MAX)?,green_x:uint(row,5,u32::MAX)?,green_y:uint(row,6,u32::MAX)?,blue_x:uint(row,7,u32::MAX)?,blue_y:uint(row,8,u32::MAX)?})}).transpose()?;
 let physical_dims=optional(database,"png_physical_dims")?.map(|row|->Result<PngPhysicalDims> {Ok(PngPhysicalDims {ppu_x:uint(row,1,u32::MAX)?,ppu_y:uint(row,2,u32::MAX)?,unit_is_meter:boolean(row,3)?})}).transpose()?;
 let timestamp=optional(database,"png_timestamp")?.map(|row|->Result<PngTimestamp> {Ok(PngTimestamp {year:uint(row,1,65535)? as u16,month:uint(row,2,255)? as u8,day:uint(row,3,255)? as u8,hour:uint(row,4,255)? as u8,minute:uint(row,5,255)? as u8,second:uint(row,6,255)? as u8})}).transpose()?;
 let text_rows=ordered(database.table("png_text")?,control)?;let mut text_chunks=allocate(text_rows.len(),control)?;for row in text_rows {let kind=match uint(row,5,2)? {0=>PngTextKind::Text,1=>PngTextKind::ZText,_=>PngTextKind::IText};text_chunks.push(PngTextChunk {keyword:reconstruct_text(control,row.text(3)?)?,value:reconstruct_text(control,row.text(4)?)?,kind,compressed:boolean(row,6)?,language_tag:reconstruct_text(control,row.text(7)?)?,translated_keyword:reconstruct_text(control,row.text(8)?)?});}
 let ancillary_rows=ordered(database.table("png_ancillary_chunk")?,control)?;let mut ancillary_chunks=allocate(ancillary_rows.len(),control)?;for row in ancillary_rows {ancillary_chunks.push(PngAncillaryChunk {kind:row.blob(3)?.try_into().map_err(|_|invalid("PNG ancillary tag must own four octets"))?,after_raster:boolean(row,4)?,data:reconstruct_blob(control,row.blob(5)?)?});}
 let image=PngImage {width:uint(row,2,u32::MAX)?,height:uint(row,3,u32::MAX)?,bit_depth:uint(row,4,255)? as u8,color_type:PngColorType::from_u8(uint(row,5,255)? as u8).map_err(invalid)?,interlace:boolean(row,6)?,samples,palette,transparency,gamma:optional_integer(database,"png_gamma",control)?,chromaticities,srgb:optional_integer(database,"png_srgb",control)?.map(|value|u8::try_from(value).map_err(|_|invalid("PNG rendering intent exceeds native precision")).and_then(|value|PngSrgbIntent::from_u8(value).map_err(invalid))).transpose()?,physical_dims,timestamp,background,text_chunks,ancillary_chunks};
 let snapshot=PngSnapshot {schema,image};snapshot.validate().map_err(invalid)?;Ok(snapshot)
}
